function bloodhoundModal(){modal('<h3>Ingest BloodHound / PlumHound</h3><p class="hint">Collector .zip/.json or PlumHound CSV. Parsing stays local.</p><input type="file" id="bh-files" accept=".zip,.json,.csv" multiple><div id="bh-out"></div>');$('#bh-files').onchange=async e=>{const files=[...e.target.files];if(!files.length)return;$('#bh-out').innerHTML='<p class="hint">Parsing…</p>';try{const r=await window.OBOL_BH._parse(files);state.bh={at:C.now(),files:r.names,stats:r.stats,findings:r.findings,lists:r.lists};let d=null;if(r.domainName){d=C.ensureDomain(state,r.domainName,{base_dn:r.domainName.split('.').map(x=>'DC='+x).join(',')});if(!state.params.domain)state.params.domain=r.domainName;if(!state.params.base_dn)state.params.base_dn=d.base_dn;state.activeContext={type:'domain',id:d.id};}
      const upd=C.applyEvidenceUpdate(state,LANES,{source:'bloodhound',context:d?{type:'domain',id:d.id}:ctx(),facts:[{id:'ad.graph.collected',evidence:'BloodHound collector data parsed'},{id:'ad.attack_paths',evidence:(r.findings||[]).length+' graph finding(s) parsed'}],domain:r.domainName||'',artifacts:{users:((r.lists||{}).allusers||{}).names||[]}});save();renderAll();let h='<p><b>'+r.names.length+' file(s) parsed.</b> '+upd.newly.length+' cards newly applicable.</p>';for(const f of r.findings||[])h+='<div class="failure"><span class="sev '+esc(f.sev)+'">'+esc(f.sev)+'</span> <b>'+esc(f.title)+'</b>'+(f.detail?'<div class="hint">'+esc(f.detail)+'</div>':'')+(f.card&&CARDS[f.card]?'<div><span class="lnk" data-bhcard="'+esc(f.card)+'">→ '+esc(CARDS[f.card].title)+'</span></div>':'')+'</div>';$('#bh-out').innerHTML=h;$('#bh-out').querySelectorAll('[data-bhcard]').forEach(x=>x.onclick=()=>{closeModal();location.hash='#/card/'+x.dataset.bhcard;});toast('BloodHound evidence applied and Path recalculated.');}catch(err){$('#bh-out').innerHTML='<p class="empty">Parse failed: '+esc(String(err))+'</p>';}};}
function viewBoxes(){let h='<h2>Boxes</h2><p class="subtitle">Targets are first-class contexts in v2. Facts, attempts, and evidence no longer bleed between hosts.</p><div class="card-actions"><button class="btn" id="add-host">Add host</button><button class="btn" id="ing-nmap">Ingest nmap</button><button class="btn" id="ing-bh">Ingest BloodHound</button></div><div class="box-grid">';for(const b of state.hosts){const active=ctx().type==='host'&&ctx().id===b.id;h+='<div class="card box-card'+(active?' active-box':'')+'"><div class="card-body"><h3>'+esc(b.name||b.hostname||b.ip||'Host')+'</h3><div class="hint">'+esc(b.ip)+' '+(b.domain?'· '+esc(b.domain):'')+'</div><div class="ports">'+(b.ports||[]).map(p=>'<span class="port-pill">'+p.port+' '+esc(p.service||'')+'</span>').join('')+'</div><label>Name<input data-bfield="name" data-bid="'+esc(b.id)+'" value="'+esc(b.name)+'"></label><label>Hostname<input data-bfield="hostname" data-bid="'+esc(b.id)+'" value="'+esc(b.hostname)+'"></label><label>Domain<input data-bfield="domain" data-bid="'+esc(b.id)+'" value="'+esc(b.domain)+'"></label><label>OS<input data-bfield="os" data-bid="'+esc(b.id)+'" value="'+esc(b.os)+'"></label><label>Notes<textarea data-bfield="notes" data-bid="'+esc(b.id)+'">'+esc(b.notes)+'</textarea></label><div class="card-actions"><button class="btn" data-work="'+esc(b.id)+'">'+(active?'Working here ✓':'Work this host')+'</button><button class="btn danger-soft" data-bdel="'+esc(b.id)+'">Remove</button></div></div></div>'; }h+='</div>';$('#view').innerHTML=h;$('#add-host').onclick=()=>{modal('<h3>Add host</h3><label>IP<input id="new-ip" placeholder="10.10.11.5"></label><label>Name<input id="new-name" placeholder="DC01"></label><div class="modal-actions"><button class="btn" id="new-save">Add</button></div>');$('#new-save').onclick=()=>{const b=C.mergeHost(state,{ip:$('#new-ip').value,name:$('#new-name').value});state.activeContext={type:'host',id:b.id};if(b.ip)state.params.target=b.ip;save();closeModal();renderAll();viewBoxes();};};$('#ing-nmap').onclick=nmapModal;$('#ing-bh').onclick=bloodhoundModal;$('#view').querySelectorAll('[data-work]').forEach(x=>x.onclick=()=>{state.activeContext={type:'host',id:x.dataset.work};const b=currentHost();if(b&&b.ip)state.params.target=b.ip;if(b&&b.domain)state.params.domain=b.domain;save();renderAll();viewBoxes();});$('#view').querySelectorAll('[data-bfield]').forEach(x=>x.oninput=()=>{const b=state.hosts.find(h=>h.id===x.dataset.bid);if(b){b[x.dataset.bfield]=x.value;if(x.dataset.bfield==='domain'&&x.value)C.ensureDomain(state,x.value);save();renderSidebar();}});$('#view').querySelectorAll('[data-bdel]').forEach(x=>x.onclick=()=>{if(confirm('Remove this host from the tracker? Activities remain in history.')){state.hosts=state.hosts.filter(h=>h.id!==x.dataset.bdel);if(ctx().id===x.dataset.bdel)state.activeContext={type:'global',id:'global'};save();renderAll();viewBoxes();}});}
