function viewTools(tool){const entries=[];for(const l of LANES)for(const c of l.cards)for(const cmd of c.commands||[])entries.push({card:c,cmd});const tools=[...new Set(entries.map(e=>e.cmd.tool))].sort();tool=tool||'__wordlists';$('#view').innerHTML='<h2>Tools</h2><p class="subtitle">Command armory and offline references. Parameters and stable option state are shared with cards.</p><div class="lane-tabs"><span class="lane-tab'+(tool==='__wordlists'?' active':'')+'" data-tool="__wordlists">Wordlists</span><span class="lane-tab'+(tool==='__scripts'?' active':'')+'" data-tool="__scripts">Scripts</span><span class="lane-tab'+(tool==='__refs'?' active':'')+'" data-tool="__refs">Repos & refs</span><span class="lane-tab'+(tool==='__workshop'?' active':'')+'" data-tool="__workshop">Exploit workshop</span>'+tools.map(t=>'<span class="lane-tab'+(t===tool?' active':'')+'" data-tool="'+esc(t)+'">'+esc(t)+'</span>').join('')+'</div><div id="tool-body"></div>';$('#view').querySelectorAll('[data-tool]').forEach(x=>x.onclick=()=>location.hash='#/tools/'+encodeURIComponent(x.dataset.tool));const body=$('#tool-body');if(tool==='__wordlists'){const cats=((window.OBOL_WORDLISTS||{}).categories)||[];body.innerHTML=cats.map(c=>'<div class="card"><div class="card-body"><h3>'+esc(c.title||c.id)+'</h3>'+(c.lists||[]).map(w=>'<div class="wl-item"><code>'+esc(w.path)+'</code><div class="note">'+esc(w.fit||'')+'</div></div>').join('')+'</div></div>').join('');return;}if(tool==='__scripts'){body.innerHTML=(window.OBOL_SCRIPTS||[]).map(s=>'<div class="card"><div class="card-body"><h3>'+esc(s.name)+'</h3><div class="hint">'+esc(s.desc||'')+'</div><pre class="report mini">'+esc(renderCmd(s.code))+'</pre></div></div>').join('');return;}if(tool==='__refs'){body.innerHTML='<div class="card"><div class="card-body">'+REPO_REFS.map(r=>'<p><a href="'+esc(r[1])+'" target="_blank" rel="noopener">'+esc(r[0])+'</a><br><code>'+esc(r[1])+'</code></p>').join('')+'</div></div>';return;}if(tool==='__workshop'){body.innerHTML='<p class="subtitle">Human-run PoC hygiene: inspect before execution, repair deliberately, and preserve your changes.</p>'+WORKSHOP.map(r=>'<div class="cmd-block"><b>'+esc(r[0])+'</b><button class="copy-btn" data-simplecopy>Copy</button><br><code>'+esc(renderCmd(r[1]))+'</code></div>').join('');body.querySelectorAll('[data-simplecopy]').forEach(b=>b.onclick=()=>navigator.clipboard.writeText(b.parentElement.querySelector('code').textContent));return;}const fs=facts();const list=entries.filter(e=>e.cmd.tool===tool);body.innerHTML='<input class="search" id="tool-search" placeholder="Filter '+esc(tool)+' commands…"><div id="tool-list"></div>';const draw=()=>{const q=$('#tool-search').value.toLowerCase();const filtered=list.filter(e=>(e.card.title+' '+e.cmd.run).toLowerCase().includes(q));$('#tool-list').innerHTML=filtered.map(e=>cardHTML(e.card,fs,true)).join('');bindCards($('#tool-list'));};$('#tool-search').oninput=draw;draw();}
