// ---------- Map / Lanes / Path ----------
const PHASE_ORDER=['Recon & Scanning','Initial Access & Web','Credential Attacks','Active Directory','Privesc & Post-Exploitation','Lateral Movement & Pivoting','Shells & Tooling','Data Services','Objectives & Reporting'];
function lanePhases(){const p=[...new Set(LANES.map(l=>l.phase))];return PHASE_ORDER.filter(x=>p.includes(x)).concat(p.filter(x=>!PHASE_ORDER.includes(x)));}
function liveCardById(id){
  if(!id)return null;
  if(CARDS[id])return CARDS[id];
  for(const lane of LANES||[])for(const card of lane.cards||[]){
    if(card&&card.id===id){card.lane=card.lane||lane.lane;CARDS[id]=card;return card;}
  }
  return null;
}
function laneById(id,title,phase){let lane=LANES.find(l=>l&&l.lane===id);if(!lane){lane={lane:id,title:title||id,phase:phase||title||id,cards:[]};LANES.push(lane);}if(!Array.isArray(lane.cards))lane.cards=[];return lane;}
function addCardAfter(lane,afterId,card){if(!lane||!card||liveCardById(card.id))return false;card.lane=card.lane||lane.lane;const i=lane.cards.findIndex(c=>c&&c.id===afterId);lane.cards.splice(i>=0?i+1:lane.cards.length,0,card);CARDS[card.id]=card;return true;}
function osAllowed(card,fs){
  const os=Array.isArray(card&&card.os)?card.os:[]; if(!os.length)return true;
  const linux=fs.has('foothold.linux')||fs.has('os.linux');
  const windows=fs.has('foothold.windows')||fs.has('os.windows')||fs.has('access.windows');
  return os.some(v=>(v==='linux'&&linux)||(v==='windows'&&windows));
}
function osFilterRanked(ranked,fs){return ranked.filter(r=>osAllowed(r.card,fs));}
function sourcePacket(ids){return {source:'complete sequential packets',packets:['offsec-pen-200-01.json','offsec-pen-200-02.json','offsec-pen-200-03.json','offsec-pen-200-04.json','offsec-pen-200-05.json','offsec-pen-200-06.json'],noteIds:ids||[]};}
