function storeCardEvidenceIntent(event){
  const btn=event.target&&event.target.closest&&event.target.closest('[data-distill]'); if(!btn)return;
  const root=btn.closest('[data-cardroot]'); if(!root)return;
  const id=root.dataset.cardroot,card=liveCardById(id)||CARDS[id]||{id,title:id};
  const ta=root.querySelector('.evidence'),copy=(state.ui.lastCopied||{})[lastCopiedKey(id)]||{};
  try{sessionStorage.setItem('obol-card-evidence-source',JSON.stringify({cardId:id,cardTitle:card.title||id,command:copy.command||'',commandId:copy.commandId||'',contextKey:C.contextKey(ctx()),at:C.now()}));}catch(_err){}
}
function readCardEvidenceIntent(){try{return JSON.parse(sessionStorage.getItem('obol-card-evidence-source')||'null');}catch(_err){return null;}}
function clearCardEvidenceIntent(){try{sessionStorage.removeItem('obol-card-evidence-source');}catch(_err){}}
function cardScopedSource(src,mode){return src&&src.cardId?'card:'+src.cardId+':intake:'+mode:'intake:'+mode;}
