  const text=$('#in-text').value||'',mode=$('#in-mode').value,r=intakeAnalyze(text,mode),source=cardScopedSource(src,r.mode);
  if(!text.trim()){toast('Paste evidence before applying.');return;}
  if(r.mode==='nmap'&&r.hosts.length){const parsed=window.OBOL_NMAP.parse(text);applyNmapScan(parsed,source);C.recordActivity(state,{cardId:src.cardId,context:ctx(),result:'evidence',outcomeFacts:[],evidence:text.slice(0,500),command:src.command||'',source});save();renderAll();}
