viewMap=function(){const fs=facts(),cov=C.coverageSummary(state,LANES,ctx());let h='<h2>Methodology Map</h2><p class="subtitle">The lifecycle board for <b>'+esc(C.contextLabel(state,ctx()))+'</b>. Counts are now context-sensitive: irrelevant services do not punish your coverage.</p><div class="card coverage-card"><div class="card-body">'+coverageHTML(cov)+'</div></div>';for(const ph of lanePhases()){h+='<h3 class="phase-h">'+esc(ph)+'</h3><div class="cards-grid">';for(const l of LANES.filter(x=>x.phase===ph)){const lc=cov.lanes.find(x=>x.lane===l.lane),done=l.cards.filter(c=>statusOf(c.id)==='done').length,ap=l.cards.filter(c=>C.applicable(c,fs)).length;h+='<div class="card"><div class="card-head" data-lane="'+esc(l.lane)+'"><span class="title">'+esc(l.title)+'</span></div><div class="card-body" data-lane="'+esc(l.lane)+'"><div class="hint">'+done+' succeeded · '+ap+' applicable now'+(lc?' · '+lc.coverage+'% relevant coverage':'')+'</div>'+(lc?covBar(lc.coverage):'')+'</div></div>';}h+='</div>';}$('#view').innerHTML=h;$('#view').querySelectorAll('[data-lane]').forEach(x=>x.onclick=()=>location.hash='#/lanes/'+x.dataset.lane);};

