  $('#view').innerHTML='<h2>Report</h2><p class="subtitle">v2.1 turns the historical ledger into a narrative and reproducible report draft. Secrets are redacted by default, and the readiness gate calls out evidence gaps before export.</p>'+(q.length?'<div class="report-gate"><h3>Report readiness · '+q.length+' item'+(q.length===1?'':'s')+' to review</h3>'+q.map(x=>'<div class="gate-'+esc(x.severity)+'">'+esc(x.message)+'</div>').join('')+'</div>':'<div class="success-box"><b>Report readiness:</b> no obvious ledger-level gaps detected.</div>')+'<div class="card-actions"><button class="btn" data-rmode="standard">Standard</button><button class="btn" data-rmode="oscp">OSCP</button><label class="opt"><input type="checkbox" id="report-secrets"'+(includeSecrets?' checked':'')+'> <span class="opt-tip">Include secrets in this export</span></label><button class="btn" id="dl-md">Download Markdown</button><button class="btn" id="print">Print / PDF</button></div><pre class="report">'+esc(md)+'</pre>';
