function showToolHelp(tool){modal(installHTML(tool));const m=$('#modal');const a=m.querySelector('[data-install-copy]');if(a)a.onclick=()=>navigator.clipboard.writeText(a.parentElement.querySelector('code').textContent);const v=m.querySelector('[data-verify-copy]');if(v)v.onclick=()=>navigator.clipboard.writeText(v.parentElement.querySelector('code').textContent);m.querySelectorAll('[data-tool-set]').forEach(b=>b.onclick=()=>{C.setToolState(state,b.dataset.tool,b.dataset.toolSet);save();closeModal();route();toast('Tool preference updated.');});}

const oldApplyPreset=applyPreset;
applyPreset=function(card,cmd,index,p){
  if(!(p&&((p.select||[]).length||p.args||p.radios)))return oldApplyPreset(card,cmd,index,p);
  const st=optState(card,cmd,index);st.selected={};st.args={};st.radio={};const opts=cmd.opts||[];
  for(const wanted of p.select||[]){const i=opts.findIndex((o,j)=>C.optionId(o,j)===wanted||(o.flag||o.script||o.arg||o.value)===wanted);if(i>=0)st.selected[C.optionId(opts[i],i)]=true;}
  for(const [wanted,val] of Object.entries(p.args||{})){const i=opts.findIndex((o,j)=>C.optionId(o,j)===wanted||o.arg===wanted);if(i>=0)st.args[C.optionId(opts[i],i)]=val;}
  for(const [group,wanted] of Object.entries(p.radios||{})){const i=opts.findIndex((o,j)=>o.radio===group&&(C.optionId(o,j)===wanted||o.value===wanted));if(i>=0)st.radio[group]=C.optionId(opts[i],i);}
  save();
};

optsHTML=function(card,cmd,index,fs){
  if(!(cmd.opts||[]).length)return'';const st=optState(card,cmd,index),cid=C.commandId(cmd,index),akey=card.id+':'+cid,advanced=!!state.ui.commandAdvanced[akey],cats={};
  for(const [i,o] of (cmd.opts||[]).entries()){if(o.advanced&&!advanced)continue;const cat=o.category||'Options';(cats[cat]=cats[cat]||[]).push([i,o]);}
  let h='';if((cmd.presets||[]).length)h+='<div class="preset-row"><span class="builder-label">Presets</span>'+cmd.presets.map((p,i)=>'<span class="variant-pill" data-preset="'+i+'" title="'+esc(p.summary||'')+'">'+esc(p.name)+'</span>').join('')+'</div>';
  h+='<div class="builder-toolbar"><span class="builder-label">Customize command</span><button class="mini-btn" data-cmd-advanced="'+esc(akey)+'">'+(advanced?'Hide advanced':'Show advanced switches')+'</button></div><div class="cmd-opts semantic-opts">';
  for(const [cat,rows] of Object.entries(cats)){h+='<div class="opt-group"><div class="opt-group-title">'+esc(cat)+'</div>';for(const [i,o] of rows){const oid=C.optionId(o,i),sug=o.needs&&o.needs.some(f=>fs.has(f)),star=sug?'<span class="opt-sug">suggested</span>':'';const name=o.semantic||o.label||o.tip||o.flag||o.script||o.value||o.arg;
    if(o.radio)h+='<label class="opt"><input type="radio" name="r-'+esc(card.id+'-'+cid+'-'+o.radio)+'" data-oradio="'+esc(o.radio)+'" data-oid="'+esc(oid)+'"'+(st.radio[o.radio]===oid?' checked':'')+'> <span class="opt-name">'+esc(name)+'</span> <code>'+esc(o.value)+'</code>'+star+(o.tip?'<span class="opt-tip">'+esc(o.tip)+'</span>':'')+'</label>';
    else if(o.script||o.flag)h+='<label class="opt"><input type="checkbox" data-osel="'+esc(oid)+'"'+(st.selected[oid]?' checked':'')+'> <span class="opt-name">'+esc(name)+'</span> <code>'+esc(o.script||o.flag)+'</code>'+star+(o.tip?'<span class="opt-tip">'+esc(o.tip)+'</span>':'')+'</label>';
    else h+='<label class="opt opt-arg-row"><span class="opt-name">'+esc(name)+'</span><code>'+esc(o.arg)+'</code><input class="opt-arg" data-oarg="'+esc(oid)+'" value="'+esc(st.args[oid]||'')+'" placeholder="'+esc(o.placeholder||'')+'">'+(o.tip?'<span class="opt-tip">'+esc(o.tip)+'</span>':'')+'</label>';
  }h+='</div>';}
  return h+'</div>';
};

const oldCardHTML=cardHTML;
cardHTML=function(c,fs,expanded,rankInfo){
  if(!expanded)return oldCardHTML(c,fs,expanded,rankInfo);const original=c.commands||[],impl=C.implementations(state,c),ordered=impl.map(x=>x.cmd);c.commands=ordered;let h=oldCardHTML(c,fs,expanded,rankInfo);c.commands=original;if(!impl.length)return h;
  const best=impl.find(x=>x.availability.status!=='missing')||impl[0],alts=impl.filter(x=>x!==best);const intro='<div class="implementation-summary"><div><span class="impl-kicker">Preferred implementation</span><b>'+esc(best.tool.label||best.tool.id)+'</b> '+toolBadge(best.availability)+'<span class="hint">Obol prefers the strongest practical implementation that is not marked missing.</span></div><div class="impl-actions"><button class="mini-btn" data-tool-help="'+esc(best.tool.id)+'">Tool help / install</button>'+(alts.length?'<span class="hint">Alternatives: '+alts.map(x=>esc(x.tool.label||x.tool.id)).join(' · ')+'</span>':'')+'</div></div>';
  h=h.replace('<div class="cmd-block"',intro+'<div class="cmd-block"');
  for(const [i,x] of impl.entries()){const cid=C.commandId(x.cmd,i),tag='<div class="implementation-head">'+(x===best?'<span class="recommended-chip">Recommended</span>':'<span class="alternative-chip">Alternative</span>')+' <b>'+esc(x.tool.label||x.tool.id)+'</b> '+toolBadge(x.availability)+' <button class="mini-btn" data-tool-help="'+esc(x.tool.id)+'">'+(x.availability.status==='missing'?'Install / restore':'I don’t have this tool')+'</button></div>';const needle='<div class="cmd-block" data-cmdid="'+esc(cid)+'">';h=h.replace(needle,needle+tag);}
  return h;
};

