bindCards=function(rootEl){oldBindCards(rootEl);rootEl.querySelectorAll('[data-tool-help]').forEach(b=>b.onclick=e=>{e.stopPropagation();showToolHelp(b.dataset.toolHelp);});rootEl.querySelectorAll('[data-cmd-advanced]').forEach(b=>b.onclick=e=>{e.stopPropagation();state.ui.commandAdvanced[b.dataset.cmdAdvanced]=!state.ui.commandAdvanced[b.dataset.cmdAdvanced];save();route();});};

