function environmentView(){const reg=(window.OBOL_TOOLS_V22||{}).tools||{},rows=Object.entries(reg).sort((a,b)=>(b[1].preference||0)-(a[1].preference||0));$('#view').innerHTML='<h2>Tools · Kali Environment</h2><p class="subtitle">Obol assumes a normal Kali installation. Only mark exceptions. Missing a preferred tool never blocks the maneuver: Obol falls back to the best available implementation and keeps install help one click away.</p><div class="env-grid">'+rows.map(([id,t])=>{const st=C.toolState(state,id);return '<div class="card env-tool"><div class="card-body"><h3>'+esc(t.label||id)+' '+toolBadge(st)+'</h3><div class="hint">'+esc(t.kali==='external'?'optional/external':'expected/common on Kali')+' · preference '+esc(t.preference||50)+'</div><code>'+esc(t.bin||id)+'</code><div class="card-actions"><button class="btn" data-tool-help="'+esc(id)+'">Install / details</button><button class="btn" data-env="available" data-tool="'+esc(id)+'">Available</button><button class="btn danger-soft" data-env="missing" data-tool="'+esc(id)+'">Missing</button></div></div></div>';}).join('')+'</div>';$('#view').querySelectorAll('[data-tool-help]').forEach(b=>b.onclick=()=>showToolHelp(b.dataset.toolHelp));$('#view').querySelectorAll('[data-env]').forEach(b=>b.onclick=()=>{C.setToolState(state,b.dataset.tool,b.dataset.env);save();environmentView();});}
