function serviceDepthHTML(rows){if(!rows.length)return'<p class="empty">No service depth is grounded yet.</p>';return '<div class="depth-grid">'+rows.slice(0,10).map(x=>'<div class="depth-row"><div><b>'+esc(x.service)+'</b><span>'+x.touched+'/'+x.relevant+' touched · '+x.succeeded+' succeeded</span></div><div class="cov-track"><span style="width:'+x.depth+'%"></span></div><b>'+x.depth+'%</b></div>').join('')+'</div>';}
