 if(!(location.hash||'').startsWith('#/path'))return;const v=$('#view');if(!v)return;C.ensure40&&C.ensure40(state);
 if(!v.querySelector('.operator-panel40')){const sub=v.querySelector('.subtitle')||v.querySelector('h2');const panel='<section class="card operator-panel40"><div class="card-body"><div><span class="operator-kicker40">Execution context</span><h3>Where are you operating from?</h3><p class="hint">This is scoped to the active target/domain. It changes command preference and a small Path ranking signal, not methodology applicability or evidence.</p></div>'+modeControls40(false)+'</div></section>';if(sub)sub.insertAdjacentHTML('afterend',panel);else v.insertAdjacentHTML('afterbegin',panel);bindMode40(v);}
