 v.querySelectorAll('.next-hero34,.next-rec34').forEach(el=>{if(el.querySelector('.operator-signal40'))return;const a=el.querySelector('a[href^="#/card/"]');if(!a)return;const id=decodeURIComponent(a.getAttribute('href').split('/').pop()),html=recommendationContext40(map.get(id));if(!html)return;const anchor=el.querySelector('.next-reach-reason34')||el.querySelector('.target-specific37')||el.querySelector('.next-signals34')||el.querySelector('p');if(anchor)anchor.insertAdjacentHTML('afterend',html);});
