 const mode=C.operatorMode40(state,ctx());root.querySelectorAll('.cmd-block').forEach(block=>{if(block.dataset.surface40)return;const cid=block.dataset.cmdid,cmd=(card.commands||[]).find((x,i)=>C.commandId(x,i)===cid);if(!cmd)return;const surface=C.commandSurface40(cmd,card);block.dataset.surface40=surface;block.classList.add('surface40-'+surface);const tool=block.querySelector('.tool');if(tool)tool.insertAdjacentHTML('afterend',' <span class="surface-badge40 '+surface+'">'+(surface==='kali'?'Kali-side':surface==='windows'?'Windows-side':surface==='target'?'target-local':'either')+'</span>');if(mode!=='either'&&(surface===mode||surface==='target'||surface==='either'))block.classList.add('operator-preferred40');});
