function dashboardHTML50(){const d=model50();if(!d)return'<p class="empty">Dashboard data is unavailable.</p>';const c=d.coverage,x=d.contracts,e=d.execution,r=d.reporting,t=d.toolReview;return '<div class="dashboard-page50"><div class="dash-hero50"><div><span class="dash-kicker50">Orange Cyber Defense North Star Dashboard · v5.0</span><h2>Project health in one place</h2><p>Methodology, command UX, copy/paste Evidence, execution context, Next Steps mapping, tool review, reporting, UI/UX policy, active-context progress, and backlog are measured here from live repository state. No combined vanity score is used.</p></div><div class="dash-score50"><b>'+c.coveragePct+'%</b><span>fully implemented</span><small>'+c.representedPct+'% represented</small></div></div><div class="dash-scope50">'+stat50('Canonical sections',c.sections,d.sourceFiles+' pinned source files')+stat50('Mapped cards',d.mappedCards,'live methodology owners')+stat50('Mapped commands',x.commands,x.adjustableCommands+' GUI-adjustable · '+x.fixedCommands+' intentionally fixed')+stat50('Canonical debt',c.gap+' gaps',c.partial+' partial · '+c.stale+' stale')+'</div><div class="dash-metrics50">'+d.metrics.map(metric50).join('')+'</div><div class="dash-grid50"><section class="dash-panel50"><div class="dash-head50"><div><span>Run → paste → interpret → decide</span><h3>Operator loop</h3></div><a href="#/intake">Evidence</a></div><div class="dash-mini50">'+stat50('Runnable cards',x.runReady+'/'+x.mappedCards,x.runPct+'%')+stat50('Evidence profiles',x.evidenceReady+'/'+x.mappedCards,x.evidencePct+'%')+stat50('Full loop',x.loopReady+'/'+x.mappedCards,x.loopPct+'%')+stat50('GUI-adjustable commands',x.adjustableCommands+'/'+x.commands,x.adjustablePct+'%')+'</div></section><section class="dash-panel50"><div class="dash-head50"><div><span>Platform + delivery</span><h3>Execution and reporting</h3></div><a href="#/report">Report</a></div><div class="dash-mini50">'+stat50('Explicit command side',e.explicit+'/'+e.commands,e.explicitPct+'%')+stat50('Kali / Windows',e.kali+' / '+e.windows,e.target+' target-local · '+e.either+' neutral/either')+stat50('Reporting traceability',r.traceable+'/'+r.mapped,r.tracePct+'%')+stat50('Finding / path roles',r.findings+' / '+r.pathOnly,'methodology remains reportable without forcing findings')+'</div></section><section class="dash-panel50"><div class="dash-head50"><div><span>Tool choices</span><h3>Keep, supplement, replace, review</h3></div><a href="#/lanes">Methodology</a></div><div class="dash-mini50">'+stat50('Reviewed decisions',t.reviewed+'/'+t.total,t.reviewedPct+'%')+stat50('Pending review',t.pending,'explicit tool-choice debt')+stat50('Keep',t.counts.keep||0,'source tool remains preferred')+stat50('Supplement / replace',(t.counts.supplement||0)+' / '+(t.counts.replace||0),'alternative or additional workflow preferred')+'</div></section><section class="dash-panel50"><div class="dash-head50"><div><span>UI / UX policy</span><h3>'+d.uiPolicy.passed+'/'+d.uiPolicy.total+' architecture checks pass</h3></div><a href="https://github.com/platocres/obol/blob/main/CHANGELOG.md" target="_blank" rel="noopener">Changelog</a></div>'+policy50(d.uiPolicy)+'</section><section class="dash-panel50 dash-backlog-panel50"><div class="dash-head50"><div><span>Canonical backlog</span><h3>Remaining work by source area</h3></div><a href="#/lanes">Full ledger</a></div>'+backlog50(d.backlog)+'</section><section class="dash-panel50"><div class="dash-head50"><div><span>Release trend</span><h3>Strict methodology progress</h3></div><span>'+c.implemented+'/'+c.sections+' current</span></div>'+trend50(d.milestones)+'</section></div>'+context50(d.active)+'<p class="dash-foot50">Partial coverage never counts as fully implemented. Fixed commands are not defects by default. Parser, reporting, UI, and dashboard work do not inflate the canonical methodology denominator.</p></div>';}
