function viewDashboard50(){if(currentDashboardOwned50())return;const v=$('#view');if(!v)return;v.innerHTML=dashboardHTML50();bindDashboard50();syncVersion50();}
function homeSummary50(){const d=model50();if(!d)return'';return '<section class="northstar-home50"><div><span>Orange Cyber Defense North Star</span><h3>'+d.coverage.coveragePct+'% fully implemented · '+d.coverage.representedPct+'% represented</h3><p>'+d.coverage.implemented+' of '+d.coverage.sections+' canonical methodology sections are fully implemented. The dedicated dashboard tracks methodology, Evidence, execution metadata, Next Steps, tool review, reporting, UI/UX policy, and backlog with hard denominators.</p></div><a class="btn" href="#/dashboard">Open dashboard</a></section>';}
