function cleanMethodology50(){if(page50()!=='lanes')return;const v=$('#view');if(!v)return;v.querySelectorAll('.dash-methodology49,.reconcile-shell43,.mindmap-shell41').forEach(x=>x.remove());const canonical=v.querySelector('.canonical-shell42');if(canonical&&!v.querySelector('.methodology-clean50'))canonical.insertAdjacentHTML('beforebegin','<div class="methodology-clean50"><b>Canonical methodology ledger</b><span>Technique-level source mapping and filters stay here. Project-wide percentages and audit health live only in the Dashboard.</span><a href="#/dashboard">Open dashboard</a></div>');}
